&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types d&#39;inquisiteur&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_dinquisiteur_0&quot; href=&quot;#Les_arch&#233;types_dinquisiteur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agent-Intra&#231;able-(Inquisiteur).html&quot; title=&quot;Agent intra&#231;able&quot;&gt;Agent intra&#231;able&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brise-Sortil&#232;ge-(Inquisiteur).html&quot; title=&quot;Brise-sortil&#232;ge&quot;&gt;Brise-sortil&#232;ge&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Foi-(Inquisiteur).html&quot; title=&quot;Chasseur de foi&quot;&gt;Chasseur de foi&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Reliques-(Inquisiteur).html&quot; title=&quot;Chasseur de reliques&quot;&gt;Chasseur de reliques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Sorci&#232;res-(Inquisiteur).html&quot; title=&quot;Chasseur de sorci&#232;res&quot;&gt;Chasseur de sorci&#232;res&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Vampires-(Inquisiteur).html&quot; title=&quot;Chasseur de vampires&quot;&gt;Chasseur de vampires&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Vigilant-(Inquisiteur).html&quot; title=&quot;D&#233;fenseur vigilant&quot;&gt;D&#233;fenseur vigilant&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exarque-(Inquisiteur).html&quot; title=&quot;Exarque&quot;&gt;Exarque&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exorciste-(Inquisiteur).html&quot; title=&quot;Exorciste&quot;&gt;Exorciste&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exterminateur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Exterminateur sacr&#233;&quot;&gt;Exterminateur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extracteur-(Inquisiteur).html&quot; title=&quot;Extracteur&quot;&gt;Extracteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Tactique-(Inquisiteur).html&quot; title=&quot;Guide tactique&quot;&gt;Guide tactique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;r&#233;tique-(Inquisiteur).html&quot; title=&quot;H&#233;r&#233;tique&quot;&gt;H&#233;r&#233;tique&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Iconoclaste-(Inquisiteur).html&quot; title=&quot;Iconoclaste&quot;&gt;Iconoclaste&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Immolateur-(Inquisiteur).html&quot; title=&quot;Immolateur&quot;&gt;Immolateur&lt;/a&gt; (Ifrit) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Infiltrateur-(Inquisiteur).html&quot; title=&quot;Infiltrateur&quot;&gt;Infiltrateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Loup-Masqu&#233;-(Inquisiteur).html&quot; title=&quot;Loup masqu&#233;&quot;&gt;Loup masqu&#233;&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mangeur-De-P&#234;ch&#233;s-(Inquisiteur).html&quot; title=&quot;Mangeur de p&#234;ch&#233;s&quot;&gt;Mangeur de p&#234;ch&#233;s&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Chasseur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Ma&#238;tre chasseur sacr&#233;&quot;&gt;Ma&#238;tre chasseur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parricide-(Inquisiteur).html&quot; title=&quot;Parricide&quot;&gt;Parricide&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Dhampir-(Race).html&quot; title=&quot;Les dhampirs&quot;&gt;Dhampir&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;cheur-(Inquisiteur).html&quot; title=&quot;Pr&#234;cheur&quot;&gt;Pr&#234;cheur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Des-Ombres-(Inquisiteur).html&quot; title=&quot;Traqueur des ombres&quot;&gt;Traqueur des ombres&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Certains inquisiteurs se concentrent davantage sur la protection de ceux qui partagent leurs croyances et leurs id&#233;aux que sur la chasse active de leurs ennemis. Ces d&#233;fenseurs vigilants travaillent souvent aux c&#244;t&#233;s de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tres&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladins&lt;/a&gt; itin&#233;rants.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Jugement partag&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Jugement_partag&#233;_Sur_0&quot; href=&quot;#Jugement_partag&#233;_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-Lintrigue.html#2&quot; title=&quot;FAQ- de l&amp;#39;Art de l&amp;#39;intrigue&quot;&gt;→&lt;/a&gt; D&#233;fenseur vigilant : Quelle est la port&#233;e de jugement partag&#233; ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;La port&#233;e est de 18 m&#232;tres. Cela sera refl&#233;t&#233; dans le prochain errata. &lt;i&gt;(Retour &#224; l&#39;&lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Vigilant-(Inquisiteur).html&quot; title=&quot;D&#233;fenseur vigilant&quot;&gt;arch&#233;type&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Quand que le d&#233;fenseur vigilant a prononc&#233; un &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#JUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;jugement&lt;/a&gt; contre ses adversaires, il peut par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; accorder &#224; tous ses alli&#233;s dans un rayon de 18 m&#232;tres les bonus ou capacit&#233;s sp&#233;ciales offertes par le jugement qu&#39;il rend. S&#39;il a plusieurs jugements actifs, ils affectent tous ses alli&#233;s. Lorsqu&#39;il le fait, le jugement ne l&#39;affecte plus, et ses effets ne durent que 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, apr&#232;s quoi cette utilisation quotidienne de jugement se termine imm&#233;diatement, m&#234;me si le combat n&#39;est pas fini. Le d&#233;fenseur vigilant ne peut changer aucun de ses jugements en un autre pendant ce round. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#JUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;jugement&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Protection des fid&#232;les (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Protection_des_fid&#232;les_Ext_1&quot; href=&quot;#Protection_des_fid&#232;les_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un d&#233;fenseur vigilant peut passer 1 minute &#224; entra&#238;ner et &#224; enseigner &#224; un groupe d&#39;alli&#233;s la meilleure fa&#231;on d&#39;&#233;viter les regards de ceux qui leur veulent du mal. Le d&#233;fenseur vigilant et ses alli&#233;s ne doivent pas &#234;tre en combat ou menac&#233;s pendant cet entra&#238;nement, et les alli&#233;s doivent pouvoir voir et entendre le d&#233;fenseur vigilant pour b&#233;n&#233;ficier de cette capacit&#233;. Cette capacit&#233; n&#39;offre aucun avantage contre les ennemis qui ont entendu ou vu l&#39;entra&#238;nement.&lt;br /&gt;&lt;br /&gt;Les alli&#233;s affect&#233;s re&#231;oivent un bonus de moral &#233;gal &#224; un quart du niveau d&#39;inquisiteur du d&#233;fenseur vigilant (minimum +1) &#224; tous leurs tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; effectu&#233;s hors combat pour &#233;viter, tromper ou remarquer d&#39;autres cr&#233;atures. Ce bonus dure 10 minutes, et le d&#233;fenseur vigilant peut affecter lui-m&#234;me et un nombre d&#39;alli&#233;s &#233;gal &#224; son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; (minimum 1). Il peut entra&#238;ner ses alli&#233;s de cette mani&#232;re une fois par jour au niveau 1, et une fois de plus par jour pour chaque tranche de 4 niveaux d&#39;inquisiteur qu&#39;il poss&#232;de, jusqu&#39;&#224; un maximum de six fois par jour au niveau 20. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#REGARDSEVERE&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;regard s&#233;v&#232;re&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Soutien des bless&#233;s (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Soutien_des_bless&#233;s_Ext_2&quot; href=&quot;#Soutien_des_bless&#233;s_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 14, un d&#233;fenseur vigilant peut sentir de fa&#231;on surnaturelle quand ses alli&#233;s sont en grand dangers et peut former un conduit mystique pour les prot&#233;ger contre les effets des blessures graves. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, chaque fois qu&#39;un ennemi confirme un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt; contre un alli&#233; dans un rayon de 9 m&#232;tres, le d&#233;fenseur vigilant peut choisir d&#39;accepter la moiti&#233; des d&#233;g&#226;ts. Dans ce cas et comme avec le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Dautrui.html&quot; title=&quot;Protection d&amp;#39;autrui&quot;&gt;protection d&#39;autrui&lt;/a&gt;&lt;/i&gt;, ses &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;r&#233;ductions de d&#233;g&#226;ts&lt;/a&gt;, ses &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistances&lt;/a&gt; et ses &lt;a class=&quot;pagelink&quot; href=&quot;Immunit&#233;-(Capacit&#233;).html&quot; title=&quot;Immunit&#233; (Ext ou Sur)&quot;&gt;immunit&#233;s&lt;/a&gt; ne s&#39;appliquent pas aux d&#233;g&#226;ts qu&#39;il subit. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#EXPLOITERLESFAIBLESSES&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;exploiter les faiblesses&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;V&#233;ritable vengeance (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;V&#233;ritable_vengeance_Sur_3&quot; href=&quot;#V&#233;ritable_vengeance_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, lorsqu&#39;un d&#233;fenseur vigilant fait appel &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#VERITABLEJUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;v&#233;ritable jugement&lt;/a&gt; sur un ennemi, si ce dernier a tu&#233; l&#39;un des alli&#233;s du d&#233;fenseur vigilant (alli&#233;s dot&#233;s d&#39;une conscience permanente, comme les membres du groupe ou les compagnons d&#39;arme, mais pas les monstres invoqu&#233;s, les compagnons animaux, les animaux de compagnie ou autres), le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; de la cible pour &#233;viter la mort est augment&#233; de 2. Si l&#39;ennemi n&#39;a bless&#233; aucun des alli&#233;s du d&#233;fenseur vigilant, le DD pour &#233;viter la mort est au contraire r&#233;duit de 2. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#VERITABLEJUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;v&#233;ritable jugement&lt;/a&gt;.
